const services = [
  {
    icon: "bx bxl-python",
    title: "Python",
    text: "Learning Python programming from fundamental concepts to application development, object-oriented programming, file handling, and databases.",
  },
  {
    icon: "bx bxl-django",
    title: "Django",
    text: "Building dynamic and scalable web applications using Django with backend development, authentication, database management, and APIs.",
  },
  {
    icon: "bx bx-code-alt",
    title: "Front End",
    text: "Developing responsive and interactive interfaces using HTML, CSS, JavaScript, and modern UI techniques.",
  },
  {
    icon: "bx bxl-react",
    title: "React JS",
    text: "Building modern interfaces using React components, JSX, props, state, hooks, and reusable UI structures.",
  },
  {
    icon: "bx bxl-javascript",
    title: "JavaScript",
    text: "Working with JavaScript fundamentals, DOM manipulation, events, ES6+, asynchronous programming, and interactive web applications.",
  },
  {
    icon: "bx bxs-data",
    title: "Databases",
    text: "Working with SQL databases such as MySQL and PostgreSQL for storing, managing, and retrieving application data.",
  },
  {
    icon: "bx bxl-jquery",
    title: "jQuery",
    text: "Learning jQuery for DOM manipulation, event handling, animations, AJAX requests, and simplified frontend development.",
  },
];

function Services() {
  return (
    <section className="section" id="services">
      <h2 className="sub-title">
        My <span>Services</span>
      </h2>

      <div className="services-list">
        {services.map((service) => (
          <div
            className="glass-card reveal"
            key={service.title}
          >
            <i className={service.icon}></i>

            <h2>{service.title}</h2>

            <p>{service.text}</p>

            <a href="#contact" className="read">
              Learn More →
            </a>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Services;
